  rows.append([f'{n} players / root {load}',sum(x['holdWins']for x in xs),sum(x['policyWins']for x in xs),sum(x['changes']for x in xs),f"{100*sum(x['meanPreEnergy']*x['n']for x in xs)/den:.1f}%",f"{100*sum(x['meanPostEnergy']*x['n']for x in xs)/den:.1f}%"])
